import{_ as e,o as n,c as t,a3 as i}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"技术决策与产品设计","description":"设计模型组合与服务策略，比较框架方案，并把 Agent 的交互、人工控制和信任边界落实为产品决策。","frontmatter":{"title":"技术决策与产品设计","description":"设计模型组合与服务策略，比较框架方案，并把 Agent 的交互、人工控制和信任边界落实为产品决策。"},"headers":[],"relativePath":"py-agent/architecture/technology-product-design/index.md","filePath":"py-agent/architecture/technology-product-design/index.md","lastUpdated":1786083160000}'),l={name:"py-agent/architecture/technology-product-design/index.md"};function s(r,a,p,o,c,d){return n(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="技术决策与产品设计" tabindex="-1">技术决策与产品设计 <a class="header-anchor" href="#技术决策与产品设计" aria-label="Permalink to &quot;技术决策与产品设计&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>系统边界明确后，还需要决定使用怎样的模型与运行平台，以及用户如何理解、控制和纠正 Agent。本分组把技术选择与产品责任放在同一决策链中：模型和框架决定系统能怎样运行，交互和人工控制决定这种能力能否被安全地委托给真实用户。</p><h2 id="_1-学习目标" tabindex="-1">1. 学习目标 <a class="header-anchor" href="#_1-学习目标" aria-label="Permalink to &quot;1. 学习目标&quot;">​</a></h2><p>完成本分组后，你应该能够：</p><ol><li>根据系统约束定义模型角色、服务拓扑、路由、故障切换和降级；</li><li>区分模型 SDK、Agent 组件、工作流运行时、RAG 层和托管平台；</li><li>通过 PoC、评分矩阵和退出条件完成框架或平台决策；</li><li>设计任务输入、真实进度、结构化产物、错误恢复和记忆控制；</li><li>区分建议、草稿、确认后执行和受限自动执行；</li><li>把审批、复核、编辑、接管和升级放在真正能改变结果的位置；</li><li>记录每项决策的依据、负面后果、回滚和复查条件。</li></ol><h2 id="_2-文章顺序" tabindex="-1">2. 文章顺序 <a class="header-anchor" href="#_2-文章顺序" aria-label="Permalink to &quot;2. 文章顺序&quot;">​</a></h2><ol><li><a href="/py-agent/architecture/technology-product-design/model-selection">模型组合与服务策略</a>：设计模型角色、服务拓扑、路由、故障切换和供应商边界。</li><li><a href="/py-agent/architecture/technology-product-design/framework-platform-selection">框架与平台选型</a>：按能力层和托管责任比较直接 SDK、LangChain、LangGraph、LlamaIndex 与平台方案。</li><li><a href="/py-agent/architecture/technology-product-design/agent-product-interaction">Agent 产品与交互设计</a>：围绕任务委托、运行状态、结果证据和失败恢复设计产品体验。</li><li><a href="/py-agent/architecture/technology-product-design/human-in-loop-trust-design">人在回路与信任设计</a>：定义人工角色、触发点、审批信息、暂停恢复和运营队列。</li></ol><p>前两篇回答“系统采用什么能力组合”，后两篇回答“用户怎样委托、观察和控制这套能力”。技术选择如果没有对应的交互和责任边界，仍然不是完整产品设计。</p><h2 id="_3-决策关系" tabindex="-1">3. 决策关系 <a class="header-anchor" href="#_3-决策关系" aria-label="Permalink to &quot;3. 决策关系&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>架构驱动因素</span></span>
<span class="line"><span>  -&gt; 模型角色、服务拓扑与路由策略</span></span>
<span class="line"><span>  -&gt; 框架和平台责任分配</span></span>
<span class="line"><span>  -&gt; 用户任务与自动化等级</span></span>
<span class="line"><span>  -&gt; 高风险动作与人工介入</span></span>
<span class="line"><span>  -&gt; 评测、试点和复查</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br></div></div><p>例如，模型能稳定生成工具调用不意味着产品可以自动退款；还要考虑业务授权、可逆性、确认成本和人工容量。反过来，如果产品承诺长任务可暂停审批，框架选型就必须验证持久状态与恢复，而不只是 Agent 演示是否成功。</p><h2 id="_4-阅读方法" tabindex="-1">4. 阅读方法 <a class="header-anchor" href="#_4-阅读方法" aria-label="Permalink to &quot;4. 阅读方法&quot;">​</a></h2><p>每篇决策文章都应保留当前基线，并比较至少一个更简单候选。记录选择时同时写出：</p><ul><li>当前任务和高风险 Slice；</li><li>不能被平均分抵消的硬约束；</li><li>候选方案及其验证数据；</li><li>选择带来的新复杂度和运营责任；</li><li>何时回滚、替换或重新评估。</li></ul><p>没有基线和复查条件的“选型”，通常只是当时的品牌偏好。</p><h2 id="_5-分组边界" tabindex="-1">5. 分组边界 <a class="header-anchor" href="#_5-分组边界" aria-label="Permalink to &quot;5. 分组边界&quot;">​</a></h2><p>本组不重复模型请求 API、LangChain/LangGraph 使用教程、评测框架或前端组件实现。基础调用位于“基础与模型”和“Agent 开发”，工作流机制位于“工作流与多 Agent”，系统化评测与生产平台位于“质量与生产”。</p><p>本组的产物是可复查的技术决策、产品状态模型和人工控制方案，而不是供应商功能列表或界面原型。</p>`,19)])])}const g=e(l,[["render",s]]);export{u as __pageData,g as default};
